-- 0077: دليل الخدمات — مرجع متكامل لكل طلب (المسار، الأدوار، التنسيق، الاشتراطات، المواصفات، التنفيذ، الاستلام، المراجع)
-- الخدمة النموذجية SV-M01 «تركيب مكيف سبليت جديد» كاملة، وبقية الكتالوج «قيد الإعداد» بمسارها وإجرائها. + تعليمة WI-M12. المولّد tools/standards/mk77_services.py
create table if not exists public.services (
  code text primary key, title text not null, unit text not null default '', cat text not null default '', icon text not null default 'book',
  status text not null default 'draft', ver text not null default '', sort int not null default 0, active boolean not null default true,
  keywords text[] not null default '{}', summary text not null default '', facts jsonb not null default '[]', routes jsonb not null default '[]',
  flow jsonb not null default '[]', raci jsonb not null default '{}', coord jsonb not null default '[]', sections jsonb not null default '[]',
  links jsonb not null default '{}', confirm text[] not null default '{}', updated_at timestamptz not null default now(), updated_by text not null default '');
alter table public.services enable row level security;
drop policy if exists services_read on public.services;
create policy services_read on public.services for select using (auth.uid() is not null);
drop policy if exists services_write on public.services;
create policy services_write on public.services for all using (public.is_admin()) with check (public.is_admin());
grant select on public.services to authenticated;
grant insert, update, delete on public.services to authenticated;


do $do$ begin
  if exists (select 1 from public.seed_marks where key = 'services_v1') then return; end if;
end $do$;
