insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($s$WI-M12$s$,$s$تركيب وحدة تكييف منفصلة (سبليت)$s$,$s$فنيو التكييف ومقاول الصيانة$s$,$s$[{"key": "purpose", "title": "الغرض والنطاق", "body": "تركيب وحدة تكييف منفصلة (سبليت) جديدة في غرفة أو مكتب قائم بطريقة واحدة مهما تغيّر الفني أو المقاول. المواصفات من بند المقطوعية LS-78 وسجل المواد المعتمدة (التكييف والتهوية). هذه التعليمة للتركيب؛ الصيانة الدورية بعد التشغيل في WI-M01. الطلب نفسه ومساره وأدواره في دليل الخدمات: «تركيب مكيف سبليت جديد»."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- تصريح عمل، وتصريح عمل ساخن للحام النحاسي، وطفاية بجانب العامل (M-01، H-07)\n- العمل على ارتفاع: سلم سليم أو منصة، وحزام أمان للوحدة الخارجية فوق الطابق الأرضي\n- عزل الكهرباء (قفل ووسم) قبل التوصيل على اللوحة\n- قفازات ونظارة عند اللحام والتعامل مع الفريون\n- في المناطق السريرية: حواجز الغبار وتعليمات مكافحة العدوى"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- الوحدة المعتمدة (LG أو Gree أو York) بالسعة المحددة في أمر العمل\n- مواسير نحاس Mueller وعزل Armaflex ¾ بوصة وغلاف حماية خارجي\n- مواسير تصريف PVC 1 بوصة وكيعان 45°، ومضخة تكثف عند الحاجة\n- قاعدة خرسانية أو حامل معتمد وعوازل اهتزاز مطاطية\n- قاطع فصل خارجي IP65 وكابل بالمقطع المحدد من الصانع\n- نيتروجين ومقياس ضغط (Manifold) ومضخة تفريغ ومقياس تفريغ\n- أداة لحام وطفاية، ميزان ماء، مثقاب كور"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | مطابقة الموديل والسعة والماركة مع أمر العمل والقائمة المعتمدة (LG أو Gree أو York — سجل المواد المعتمدة) | مطابق |\n| 2 | تحديد موقع الوحدة الداخلية: على جدار متين، بعيداً عن مصادر الحرارة، لا تنفخ مباشرة على سرير أو مكتب، وبمسافات الصانع حولها | الموقع معتمد من المنشأة |\n| 3 | تحديد موقع الوحدة الخارجية بالتنسيق مع المرافق: تهوية كافية، وصول آمن للصيانة، ولا تشوّه الواجهة ولا تصرف على ممر | الموقع معتمد من المرافق |\n| 4 | إصدار تصريح العمل (M-01) وتصريح العمل الساخن قبل اللحام النحاسي، وطفاية حريق في الموقع | التصاريح سارية |\n| 5 | حماية المكان: تغطية الأثاث والأجهزة، وحاجز غبار؛ وفي المناطق السريرية حسب تقييم مكافحة العدوى (ICRA) | المكان محمي |\n| 6 | تثبيت لوحة التعليق بالميزان، والثقب بميل خفيف للخارج مع كم حماية للفتحة | أفقي ومحكم |\n| 7 | تمديد مواسير النحاس Mueller بأقل عدد من الانحناءات، وعزلها بـ Armaflex لا يقل عن ¾ بوصة، وغلاف حماية من الشمس للجزء الخارجي | العزل متصل بلا فراغات |\n| 8 | تمديد التصريف PVC قطر 1 بوصة بميل مستمر وكيعان 45° فقط، أو مضخة تكثف عند تعذر الميل؛ واختباره بسكب ماء في الصينية | الماء يتصرف كاملاً |\n| 9 | تركيب الوحدة الخارجية على قاعدة خرسانية أو حامل معتمد بعوازل اهتزاز مطاطية | ثابتة بلا اهتزاز |\n| 10 | الكهرباء: دائرة وقاطع مستقلان لكل وحدة حسب بيانات الصانع، وقاطع فصل خارجي IP65 بجوار الوحدة الخارجية | القاطع مطابق |\n| 11 | اختبار التسريب بضغط النيتروجين، ثم التفريغ (Vacuum) حسب قيمة الصانع قبل فتح الصمامات | لا تسريب والتفريغ ثابت |\n| 12 | فتح الصمامات والتشغيل: قياس حرارة الهواء الخارج من الوحدة وتيار التشغيل، والتأكد من الضجيج والتصريف | ضمن بيانات الصانع |\n| 13 | التنظيف وإعادة المكان، ووسم الوحدة برقم الأصل، وتصويرها، وتسليم الضمان وكتيّب الصانع | الأصل مسجل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| التركيب | عند كل طلب معتمد |\n| أول صيانة وقائية | ضمن خطة WI-M01 بعد التشغيل |"}, {"key": "accept", "title": "معايير القبول", "body": "- الماركة والسعة مطابقتان لأمر العمل والقائمة المعتمدة\n- لا تسريب فريون ولا ماء، والتصريف يعمل بالميل أو المضخة\n- العزل متصل والمواسير الخارجية محمية من الشمس\n- قاطع مستقل وقاطع خارجي IP65\n- لا اهتزاز ولا ضجيج غير طبيعي\n- الوحدة موسومة برقم أصل ومسجلة، والضمان (سنتان للوحدة و5 سنوات للكمبروسر) مسلَّم"}, {"key": "donts", "title": "ممنوعات", "body": "- اللحام بلا تصريح عمل ساخن وطفاية\n- تصريف الماء على الواجهة أو السطح أو الممرات\n- ماركة أو سعة غير معتمدة أو وحدة مستعملة\n- توصيل الوحدة على مقبس أو دائرة مشتركة\n- تشغيل الوحدة قبل التفريغ\n- ترك فتحات الجدار بلا إغلاق وعزل"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود قائمة تحقق أمر العمل؛ لا يُغلق الأمر قبل إكمالها وإرفاق صور قبل وبعد.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "M-01 · H-07 · G-05 · G-06 · F-03"}]$s$::jsonb,'wi',119,'wrench',$s$أنظمة التكييف$s$,'MNT',$s$["مطابقة الموديل والسعة والماركة مع أمر العمل والقائمة المعتمدة (LG أو Gree أو York — سجل المواد المعتمدة)", "تحديد موقع الوحدة الداخلية: على جدار متين، بعيداً عن مصادر الحرارة، لا تنفخ مباشرة على سرير أو مكتب، وبمسافات الصانع حولها", "تحديد موقع الوحدة الخارجية بالتنسيق مع المرافق: تهوية كافية، وصول آمن للصيانة، ولا تشوّه الواجهة ولا تصرف على ممر", "إصدار تصريح العمل (M-01) وتصريح العمل الساخن قبل اللحام النحاسي، وطفاية حريق في الموقع", "حماية المكان: تغطية الأثاث والأجهزة، وحاجز غبار؛ وفي المناطق السريرية حسب تقييم مكافحة العدوى (ICRA)", "تثبيت لوحة التعليق بالميزان، والثقب بميل خفيف للخارج مع كم حماية للفتحة", "تمديد مواسير النحاس Mueller بأقل عدد من الانحناءات، وعزلها بـ Armaflex لا يقل عن ¾ بوصة، وغلاف حماية من الشمس للجزء الخارجي", "تمديد التصريف PVC قطر 1 بوصة بميل مستمر وكيعان 45° فقط، أو مضخة تكثف عند تعذر الميل؛ واختباره بسكب ماء في الصينية", "تركيب الوحدة الخارجية على قاعدة خرسانية أو حامل معتمد بعوازل اهتزاز مطاطية", "الكهرباء: دائرة وقاطع مستقلان لكل وحدة حسب بيانات الصانع، وقاطع فصل خارجي IP65 بجوار الوحدة الخارجية"]$s$::jsonb,$s${"ppe": ["gloves", "goggles", "ladder"], "steps": [{"i": "clipboard", "t": {"ar": "طابق الموديل والسعة مع أمر العمل", "en": "Match model and capacity to the work order", "ur": "ماڈل اور گنجائش کو ورک آرڈر سے ملائیں", "bn": "মডেল ও ক্ষমতা ওয়ার্ক অর্ডারের সাথে মিলান", "hi": "मॉडल और क्षमता को वर्क ऑर्डर से मिलाएं", "tl": "Itugma ang modelo at kapasidad sa work order"}}, {"i": "permit", "t": {"ar": "تصريح العمل والطفاية قبل اللحام", "en": "Work permit and extinguisher before brazing", "ur": "ویلڈنگ سے پہلے ورک پرمٹ اور آگ بجھانے والا آلہ", "bn": "ঝালাইয়ের আগে ওয়ার্ক পারমিট ও অগ্নিনির্বাপক", "hi": "वेल्डिंग से पहले वर्क परमिट और अग्निशामक", "tl": "Work permit at extinguisher bago mag-braze"}}, {"i": "drop", "t": {"ar": "صرف بميل مستمر — اختبره بالماء", "en": "Drain with a continuous slope — test with water", "ur": "ڈرین مسلسل ڈھلوان پر — پانی سے چیک کریں", "bn": "ড্রেন সবসময় ঢালু — পানি দিয়ে পরীক্ষা করুন", "hi": "ड्रेन लगातार ढलान पर — पानी से जांचें", "tl": "Tuloy-tuloy na pababa ang drain — subukan sa tubig"}}, {"i": "power", "t": {"ar": "قاطع مستقل لكل وحدة", "en": "A separate breaker for each unit", "ur": "ہر یونٹ کا الگ بریکر", "bn": "প্রতিটি ইউনিটের আলাদা ব্রেকার", "hi": "हर यूनिट का अलग ब्रेकर", "tl": "Hiwalay na breaker sa bawat unit"}}, {"i": "gauge", "t": {"ar": "اختبار الضغط والتفريغ قبل التشغيل", "en": "Pressure and vacuum test before start-up", "ur": "چلانے سے پہلے پریشر اور ویکیوم ٹیسٹ", "bn": "চালুর আগে প্রেসার ও ভ্যাকুয়াম টেস্ট", "hi": "चालू करने से पहले प्रेशर और वैक्यूम टेस्ट", "tl": "Pressure at vacuum test bago paandarin"}}, {"i": "tag", "t": {"ar": "وسّم الوحدة وصوّرها", "en": "Label and photograph the unit", "ur": "یونٹ پر لیبل لگائیں اور تصویر لیں", "bn": "ইউনিটে লেবেল দিন ও ছবি তুলুন", "hi": "यूनिट पर लेबल लगाएं और फोटो लें", "tl": "Lagyan ng label at kunan ng larawan ang unit"}}], "donts": [{"i": "nofire", "t": {"ar": "لا لحام بلا تصريح", "en": "No brazing without a permit", "ur": "پرمٹ کے بغیر ویلڈنگ نہیں", "bn": "পারমিট ছাড়া ঝালাই নয়", "hi": "परमिट के बिना वेल्डिंग नहीं", "tl": "Bawal mag-braze nang walang permit"}}, {"i": "nodrop", "t": {"ar": "لا تصريف على الواجهة أو السطح", "en": "No drain water onto the facade or roof", "ur": "دیوار یا چھت پر پانی نہ گرائیں", "bn": "দেয়াল বা ছাদে পানি ফেলবেন না", "hi": "दीवार या छत पर पानी न गिराएं", "tl": "Huwag padaluyin ang tubig sa pader o bubong"}}]}$s$::jsonb) on conflict (code) do nothing;
  insert into public.services(code,title,unit,cat,icon,status,sort,keywords,summary,facts,routes,flow,raci,coord,sections,links,confirm) values ($s$SV-M01$s$,$s$تركيب مكيف سبليت جديد$s$,$s$MNT$s$,$s$التكييف والتهوية$s$,$s$wrench$s$,$s$draft$s$,10,array[$s$مكيف$s$,$s$مكيفات$s$,$s$تكييف$s$,$s$سبليت$s$,$s$split$s$,$s$وحدة تكييف$s$,$s$تبريد$s$,$s$تركيب مكيف$s$,$s$مكيف جديد$s$,$s$حر$s$,$s$حرارة الغرفة$s$]::text[],$s$إضافة وحدة تكييف منفصلة (سبليت) جديدة لغرفة أو مكتب أو منطقة قائمة: من يطلب، وكيف يُصنَّف الطلب، ومن يعتمد وينفّذ ويستلم، والمواصفات المعتمدة وطريقة التركيب. المكيف القائم المتعطل ليس هنا — له «بلاغ عطل تكييف».$s$,$s$[["من يطلب", "مدير المنشأة أو رئيس القسم المستفيد"], ["المالك", "قسم الصيانة"], ["يعتمد التكلفة", "مدير الإدارة"], ["يستلم", "المنشأة مع الصيانة"], ["الإجراء الحاكم", "G-05، ويصبح G-02 إن تحوّل إلى مشروع"]]$s$::jsonb,$s$[{"t": "مكيف أو مكيفان لغرفة قائمة، دون تعديل معماري، وضمن سعة الكهرباء القائمة", "out": "أعمال صيانة صغيرة تنفذها الصيانة", "kind": "mnt", "proc": "G-05", "unit": "MNT", "main": true}, {"t": "عدة غرف، أو منطقة سريرية بضغط محكوم (عزل، عمليات، تعقيم)، أو يحتاج لوحة أو كابلاً جديداً أو تعديل واجهة، أو تتجاوز التكلفة حد المشروع", "out": "طلب دراسة مشروع (R-01)", "kind": "prj", "proc": "G-02", "unit": "PRJ"}, {"t": "المكيف موجود لكنه متعطل أو يحتاج استبدالاً بمثله", "out": "بلاغ صيانة، لا طلب تركيب (R-02)", "kind": "mnt", "proc": "G-05", "unit": "MNT"}]$s$::jsonb,$s$[{"u": "BEN", "a": "يرفع الطلب من المنصة على رقم الغرفة، مع الاستخدام وعدد الأشخاص والأجهزة المولدة للحرارة وصور الغرفة والجدار الخارجي", "o": "طلب برقم مرجعي", "sla": "—", "ref": "G-01 · R-16"}, {"u": "FAC", "a": "يتحقق من اكتمال البيانات ويصنّف المسار: صيانة صغيرة أم مشروع", "o": "إحالة للقسم المختص", "sla": "يوم عمل", "ref": "G-01 · R-01 · R-02"}, {"u": "MNT", "a": "كشف ميداني: السعة المطلوبة، موقع الوحدتين، مسار المواسير والتصريف، سعة اللوحة والقاطع، وتقدير التكلفة", "o": "تقرير كشف وتقدير", "sla": "5 أيام عمل", "ref": "G-05"}, {"u": "BEN", "a": "في المناطق السريرية: تقييم مكافحة العدوى بالمنشأة (ICRA) وموافقتها على طريقة العمل", "o": "موافقة مكافحة العدوى", "sla": "يومان", "ref": "R-11", "opt": true}, {"u": "DIR", "a": "اعتماد التكلفة: ضمن بنود عقد التشغيل والصيانة وأسعاره، وما خرج عنها يصبح إجراء شراء مستقلاً", "o": "اعتماد", "sla": "3 أيام عمل", "ref": "A-17"}, {"u": "PROC", "a": "شراء الوحدة من القائمة المعتمدة إن لم تكن ضمن عقد الصيانة", "o": "أمر شراء", "sla": "حسب دورة الشراء", "ref": "M-26", "opt": true}, {"u": "MNT", "a": "جدولة التنفيذ مع المنشأة، وإصدار تصريح العمل وتصريح العمل الساخن للحام", "o": "موعد وتصريح", "sla": "قبل التنفيذ بيومين", "ref": "M-01 · H-07"}, {"u": "SAF", "a": "اعتماد تصريح العمل الساخن، وعزل كواشف الدخان في نقطة العمل فقط عند الحاجة بإجراء التعطيل", "o": "تصريح ساخن", "sla": "يوم التنفيذ", "ref": "H-07 · H-01"}, {"u": "GEN", "a": "تهيئة الموقع: حماية الأثاث، نظافة أثناء العمل وبعده، ومسار نفايات الأعمال", "o": "موقع مهيأ", "sla": "يوم التنفيذ", "ref": "G-10", "opt": true}, {"u": "MNT", "a": "التنفيذ وفق تعليمة العمل WI-M12 (بالفريق الذاتي أو مقاول الصيانة)", "o": "وحدة مركبة ومختبرة", "sla": "يوم إلى يومين", "ref": "WI-M12"}, {"u": "BEN", "a": "الاستلام مع الصيانة: التبريد، التصريف، الضجيج، نظافة المكان، وتوقيع إغلاق أمر العمل", "o": "توقيع الاستلام", "sla": "يوم", "ref": "G-05"}, {"u": "MNT", "a": "تسجيل الوحدة أصلاً برقم ووسمها، وحفظ الضمان، وإدراجها في الصيانة الوقائية", "o": "أصل مسجل وخطة صيانة", "sla": "يوم", "ref": "F-03 · G-06 · WI-M01"}, {"u": "FAC", "a": "إغلاق الطلب الأصلي وإبلاغ المنشأة", "o": "طلب مغلق", "sla": "يوم", "ref": "G-01"}]$s$::jsonb,$s${"cols": ["BEN", "FAC", "MNT", "SAF", "GEN", "DIR", "PROC"], "rows": [{"task": "رفع الطلب وبياناته", "v": {"BEN": "R/A", "FAC": "I"}}, {"task": "تصنيف المسار (صيانة أم مشروع)", "v": {"FAC": "R/A", "MNT": "C", "BEN": "I", "DIR": "I"}}, {"task": "الكشف وتحديد السعة والموقع", "v": {"MNT": "R/A", "BEN": "C", "FAC": "C"}}, {"task": "موافقة مكافحة العدوى (المناطق السريرية)", "v": {"BEN": "R/A", "MNT": "C"}}, {"task": "اعتماد التكلفة", "v": {"MNT": "R", "DIR": "A", "PROC": "C"}}, {"task": "الشراء خارج عقد الصيانة", "v": {"PROC": "R", "MNT": "C", "DIR": "A"}}, {"task": "تصريح العمل والعمل الساخن", "v": {"MNT": "R", "SAF": "A", "BEN": "I"}}, {"task": "تهيئة الموقع والنظافة", "v": {"GEN": "R/A", "BEN": "C", "MNT": "I"}}, {"task": "التنفيذ", "v": {"MNT": "R/A", "SAF": "C", "BEN": "I"}}, {"task": "الاختبار والاستلام", "v": {"MNT": "R", "BEN": "A", "FAC": "I"}}, {"task": "تسجيل الأصل والصيانة الوقائية", "v": {"MNT": "R/A", "FAC": "C"}}, {"task": "إغلاق الطلب", "v": {"FAC": "R/A", "BEN": "I"}}]}$s$::jsonb,$s$[{"u": "MNT", "why": "مالك الخدمة: الكشف والتقدير والتنفيذ والتسجيل والصيانة بعد التشغيل."}, {"u": "FAC", "why": "استقبال الطلب وتصنيفه، وموقع الوحدة الخارجية على الواجهة، وسجل المواقع والغرف."}, {"u": "BEN", "why": "المنشأة: بيانات الغرفة والاستخدام، ومكافحة العدوى للمناطق السريرية، وتوقيع الاستلام."}, {"u": "SAF", "why": "العمل الساخن (اللحام النحاسي) وأي عزل لكواشف الدخان في نقطة العمل."}, {"u": "GEN", "why": "حماية الأثاث والنظافة ونقل نفايات الأعمال في المناطق المشغولة."}, {"u": "DIR", "why": "اعتماد التكلفة ضمن الصلاحية، أو الإحالة لإجراء شراء."}, {"u": "PROC", "why": "الشراء من القائمة المعتمدة إن لم تكن الوحدة ضمن عقد الصيانة."}, {"u": "PRJ", "why": "إن تحقق أحد معايير المشروع (R-01) يتحول الطلب إلى دراسة مشروع."}, {"u": "IT", "why": "فقط لتكييف غرف الخوادم والاتصالات: السعة والتشغيل الاحتياطي يُنسقان مع تقنية المعلومات."}]$s$::jsonb,$s$[{"key": "need", "title": "ما يرفقه مقدم الطلب", "body": "- رقم الغرفة من سجل المواقع (لا يُقبل طلب بلا موقع — R-16)\n- استخدام الغرفة: مكتب، عيادة، انتظار، مستودع، غرفة خوادم…\n- المساحة التقريبية وعدد الأشخاص المعتادين\n- الأجهزة المولدة للحرارة في الغرفة (أجهزة طبية، حواسيب، طابعات)\n- صورة للغرفة وصورة للجدار الخارجي المقترح للوحدة الخارجية\n- هل الغرفة سريرية أو ذات ضغط محكوم (عزل، عمليات، تعقيم)؟"}, {"key": "reqs", "title": "الاشتراطات", "body": "- الماركات المعتمدة فقط: LG أو Gree أو York (سجل المواد M-26 — من القائمة)، بكفاءة مطابقة لاشتراطات SASO وفريون صديق للبيئة.\n- مواسير النحاس Mueller، وعزل Armaflex لا يقل عن ¾ بوصة، وغلاف حماية من الشمس للمواسير الخارجية.\n- التصريف PVC قطر 1 بوصة بكيعان 45° فقط، ومضخة تكثف عند تعذر الميل؛ ولا يُصرف الماء على الواجهة أو السطح أو الممرات.\n- الوحدة الخارجية على قاعدة خرسانية أو حامل معتمد بعوازل اهتزاز مطاطية، وقاطع فصل خارجي IP65.\n- دائرة وقاطع مستقلان لكل وحدة حسب بيانات الصانع.\n- اختبار التفريغ والتسريب قبل التشغيل.\n- الضمان: سنتان للوحدة و5 سنوات للكمبروسر.\n- المناطق السريرية ذات الضغط المحكوم: لا تُركّب وحدة منفصلة إلا بموافقة هندسية ومكافحة العدوى (ASHRAE 170).\n- المصدر: بند المقطوعية LS-78، وسجل المواد M-26، وبطاقة دليل المواصفات G-22."}, {"key": "accept", "title": "متى يُعتبر العمل مقبولاً", "body": "- الماركة والسعة مطابقتان للاعتماد\n- الغرفة تبرد كما هو مطلوب والضجيج طبيعي\n- لا تسريب ماء ولا فريون، والتصريف يعمل\n- لا مواسير أو كابلات ظاهرة بلا تغليف، والفتحات مغلقة\n- المكان نظيف ومُعاد كما كان\n- الوحدة موسومة برقم أصل ومدرجة في الصيانة الوقائية، والضمان محفوظ"}, {"key": "donts", "title": "ممنوعات", "body": "- شراء المكيف من المنشأة أو من متبرع وتركيبه دون المرور بالصيانة — أي وحدة تبرع تلتزم بالقائمة المعتمدة وتعليمة التركيب وتُستلم بالطريقة نفسها\n- تركيب ماركة أو سعة غير معتمدة أو وحدة مستعملة\n- توصيل المكيف على مقبس عادي أو دائرة مشتركة\n- تصريف الماء على الواجهة أو السطح\n- اللحام بلا تصريح عمل ساخن\n- تشغيل الوحدة دون تسجيلها أصلاً"}, {"key": "faq", "title": "أسئلة متكررة", "body": "- متبرع يريد تركيب مكيفات؟ يُرفع الطلب نفسه، وتحدد الصيانة السعة والموقع، ويلتزم المتبرع بالماركات المعتمدة وتعليمة التركيب، وتستلم الصيانة العمل وتسجل الأصول.\n- المكيف القائم لا يبرد؟ هذا بلاغ عطل تكييف لا طلب تركيب.\n- غرفة خوادم؟ يُنسَّق مع تقنية المعلومات لأن السعة والتشغيل الاحتياطي يختلفان.\n- أكثر من غرفتين أو منطقة كاملة؟ يُحال إلى المشاريع لدراسته (R-01)."}]$s$::jsonb,$s${"procs": ["G-01", "G-05", "G-02", "M-01", "H-07", "H-01", "G-10", "F-03", "G-06"], "rules": ["R-01", "R-02", "R-11", "R-15", "R-16", "R-45"], "auth": ["A-17", "A-14"], "wis": ["WI-M12", "WI-M01"], "ls": ["LS-78", "LS-22"], "mats": ["M-26"], "stds": ["ASHRAE 170"], "cards": ["G-22"], "ho": ["HO-12", "HO-13", "HO-16", "HO-06"]}$s$::jsonb,array[$s$تصنيف «مكيف أو مكيفين لغرفة قائمة» كأعمال صيانة صغيرة (لا مشروع) — يحتاج تأكيد مدير الإدارة$s$,$s$مهلة الكشف الميداني 5 أيام عمل ومهلة اعتماد التكلفة 3 أيام عمل — مقترحتان$s$,$s$مراجعة مكافحة العدوى للعبارة الخاصة بالمناطق ذات الضغط المحكوم$s$]::text[]) on conflict (code) do nothing;
  insert into public.services(code,title,unit,cat,icon,status,sort,keywords,summary,facts,routes,flow,raci,coord,sections,links,confirm) values ($s$SV-M02$s$,$s$بلاغ عطل تكييف$s$,$s$MNT$s$,$s$التكييف والتهوية$s$,$s$wrench$s$,$s$planned$s$,20,array[$s$مكيف$s$,$s$تكييف$s$,$s$لا يبرد$s$,$s$تسريب مكيف$s$,$s$عطل مكيف$s$]::text[],$s$المكيف لا يبرد أو يسرّب ماء أو يصدر صوتاً: بلاغ صيانة تصحيحية بالأولوية.$s$,$s$[]$s$::jsonb,$s$[{"t": "عطل في مكيف قائم", "kind": "mnt", "proc": "G-05", "unit": "MNT", "main": true}, {"t": "توقف التكييف عن منطقة حرجة (عمليات، عناية، خوادم)", "kind": "emerg", "proc": "G-11", "unit": "MNT"}]$s$::jsonb,$s$[]$s$::jsonb,$s${}$s$::jsonb,$s$[]$s$::jsonb,$s$[]$s$::jsonb,$s${}$s$::jsonb,'{}'::text[]) on conflict (code) do nothing;
  insert into public.services(code,title,unit,cat,icon,status,sort,keywords,summary,facts,routes,flow,raci,coord,sections,links,confirm) values ($s$SV-M03$s$,$s$نقل مكيف أو إزالته$s$,$s$MNT$s$,$s$التكييف والتهوية$s$,$s$wrench$s$,$s$planned$s$,21,array[$s$نقل مكيف$s$,$s$إزالة مكيف$s$,$s$فك مكيف$s$]::text[],$s$نقل وحدة قائمة لموقع آخر أو إزالتها مع إغلاق الفتحات وتحديث سجل الأصول.$s$,$s$[]$s$::jsonb,$s$[{"t": "نقل أو إزالة وحدة", "kind": "mnt", "proc": "G-05", "unit": "MNT", "main": true}]$s$::jsonb,$s$[]$s$::jsonb,$s${}$s$::jsonb,$s$[]$s$::jsonb,$s$[]$s$::jsonb,$s${}$s$::jsonb,'{}'::text[]) on conflict (code) do nothing;
  insert into public.services(code,title,unit,cat,icon,status,sort,keywords,summary,facts,routes,flow,raci,coord,sections,links,confirm) values ($s$SV-M04$s$,$s$نقطة كهرباء أو مقبس جديد$s$,$s$MNT$s$,$s$الكهرباء والإنارة$s$,$s$bolt$s$,$s$planned$s$,22,array[$s$مقبس$s$,$s$فيش$s$,$s$نقطة كهرباء$s$,$s$كهرباء$s$,$s$توصيلة$s$]::text[],$s$إضافة مقبس أو نقطة كهرباء لجهاز أو مكتب، بالتحقق من سعة الدائرة.$s$,$s$[]$s$::jsonb,$s$[{"t": "نقطة أو مقبس في غرفة قائمة", "kind": "mnt", "proc": "G-05", "unit": "MNT", "main": true}, {"t": "لجهاز طبي جديد", "kind": "siteprep", "proc": "G-07", "unit": "MED"}]$s$::jsonb,$s$[]$s$::jsonb,$s${}$s$::jsonb,$s$[]$s$::jsonb,$s$[]$s$::jsonb,$s${}$s$::jsonb,'{}'::text[]) on conflict (code) do nothing;
  insert into public.services(code,title,unit,cat,icon,status,sort,keywords,summary,facts,routes,flow,raci,coord,sections,links,confirm) values ($s$SV-M05$s$,$s$إنارة جديدة أو تعديلها$s$,$s$MNT$s$,$s$الكهرباء والإنارة$s$,$s$bolt$s$,$s$planned$s$,23,array[$s$إنارة$s$,$s$إضاءة$s$,$s$لمبة$s$,$s$كشاف$s$]::text[],$s$إضافة إنارة أو تحسينها أو استبدالها بـ LED.$s$,$s$[]$s$::jsonb,$s$[{"t": "إنارة في غرفة قائمة", "kind": "mnt", "proc": "G-05", "unit": "MNT", "main": true}, {"t": "إعادة تصميم إنارة منطقة كاملة", "kind": "prj", "proc": "G-02", "unit": "PRJ"}]$s$::jsonb,$s$[]$s$::jsonb,$s${}$s$::jsonb,$s$[]$s$::jsonb,$s$[]$s$::jsonb,$s${}$s$::jsonb,'{}'::text[]) on conflict (code) do nothing;
